	MOVQ    120(SP), R15
	MOVLQSX (R15)(R14*4), R13

imp_ml_cost_ok:
	TESTQ R12, R12
	JS    imp_off_norm
	MOVQ  R12, R14
	ANDQ  $0x03, R14
	JMP   imp_of_cost

imp_off_norm:
	MOVQ R11, R14
	SUBQ R10, R14
	ADDQ $0x03, R14

imp_of_cost:
	BSRQ    R14, R14
	MOVQ    104(SP), R15
	MOVLQSX (R15)(R14*4), R14
	ADDQ    R14, R13
	MOVQ    R9, R14
	IMULQ   32(SP), R14
	SARQ    $0x0a, R14
	SUBQ    R14, R13
	TESTQ   R13, R13
	JLE     imp_est_ok
	XORQ    R9, R9
	MOVQ    $0x0000000000100010, R13

imp_est_ok:
	CMPQ  224(SP), $0x00100010
	JGE   imp_accept
	MOVQ  R11, R14
	SUBQ  200(SP), R14
	IMULQ 32(SP), R14
	SARQ  $0x0a, R14
	ADDQ  R13, R14
	SUBQ  224(SP), R14
	TESTQ R14, R14
	JGE   imp_next

imp_accept:
	MOVQ R10, 192(SP)
	MOVQ R11, 200(SP)
	MOVQ R9, 208(SP)
	MOVQ R12, 216(SP)
	MOVQ R13, 224(SP)

imp_next:
	MOVQ 232(SP), R9
	CMPQ R9, 240(SP)
	JL   improve_batch
	MOVQ 248(SP), R9
	CMPQ R9, $0x00
	JE   stage0_done
	CMPQ R9, $0x01
	JE   stage1_done
	CMPQ R9, $0x02
	JE   stage2_done
	CMPQ R9, $0x03
	JE   stage3_done
	CMPQ R9, $0x04
	JE   stage4_done
	CMPQ R9, $0x05
	JE   stage5_done
	JMP  stage6_done

done:
	MOVQ 48(SP), CX
	SUBQ 40(SP), CX
	MOVQ CX, 88(AX)
	MOVQ 64(SP), CX
	SUBQ 56(SP), CX
	SHRQ $0x04, CX
	MOVQ CX, 96(AX)
	MOVQ 80(SP), CX
	MOVQ CX, 104(AX)
	MOVQ 88(SP), CX
	MOVQ CX, 112(AX)
	MOVQ 96(SP), CX
	MOVQ CX, 120(AX)
	MOVQ BX, 128(AX)
	RET
